{
  "up": "Select activities.standard_type, activities.standard_relation, activities.standard_value, activities.standard_units, compound_structures.canonical_smiles, molecule_dictionary.chembl_id as chembl_id from activities inner join assays on activities.assay_id = assays.assay_id inner join compound_records on activities.record_id = compound_records.record_id inner join molecule_dictionary on compound_records.molregno = molecule_dictionary.molregno inner join compound_structures on molecule_dictionary.molregno = compound_structures.molregno where assays.chembl_id = 'CHEMBL1054503' and activities.standard_value is not null and activities.standard_relation = '='"
}
